];

interface EditAPIKeysProps {
  organizationId: string;
  apiKeys: TApiKeyWithEnvironmentPermission[];
  locale: TUserLocale;
  workspaces: TOrganizationWorkspace[];
  isFormbricksCloud: boolean;
  canGrantOrganizationWriteAccess: boolean;
}

export const EditAPIKeys = ({
  organizationId,
  apiKeys,
  locale,
  workspaces,
  isFormbricksCloud,
  canGrantOrganizationWriteAccess,
}: Readonly<EditAPIKeysProps>) => {
  const { t } = useTranslation();
  const [isAddAPIKeyModalOpen, setIsAddAPIKeyModalOpen] = useState(false);
  const [isDeleteKeyModalOpen, setIsDeleteKeyModalOpen] = useState(false);
  const [apiKeysLocal, setApiKeysLocal] = useState<TApiKeyRow[]>(apiKeys);
  const [activeKey, setActiveKey] = useState<TApiKeyWithEnvironmentPermission | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [viewPermissionsOpen, setViewPermissionsOpen] = useState(false);
  const [isRotateKeyModalOpen, setIsRotateKeyModalOpen] = useState(false);
  const [rotatedKey, setRotatedKey] = useState<string | null>(null);

  const handleOpenDeleteKeyModal = (e: React.MouseEvent, apiKey: TApiKeyWithEnvironmentPermission) => {
    e.preventDefault();
    setActiveKey(apiKey);
    setIsDeleteKeyModalOpen(true);
  };

  const handleDeleteKey = async () => {
    if (!activeKey) return;
    setIsLoading(true);
    const deleteApiKeyResponse = await deleteApiKeyAction({ id: activeKey.id });
    if (deleteApiKeyResponse?.data) {
      const updatedApiKeys = apiKeysLocal?.filter((apiKey) => apiKey.id !== activeKey.id) || [];
      setApiKeysLocal(updatedApiKeys);
      toast.success(t("workspace.api_keys.api_key_deleted"));
      setIsDeleteKeyModalOpen(false);
      setIsLoading(false);
    } else {
      toast.error(t("workspace.api_keys.unable_to_delete_api_key"));
      setIsDeleteKeyModalOpen(false);
      setIsLoading(false);
    }
  };

  const handleRotateKey = async () => {
    if (!activeKey) return;
    setIsLoading(true);
    const rotateApiKeyResponse = await rotateApiKeyAction({ apiKeyId: activeKey.id });
    if (rotateApiKeyResponse?.data) {
      setRotatedKey(rotateApiKeyResponse.data.actualKey ?? null);
      const updatedApiKeys =
        apiKeysLocal?.map((apiKey) => {
          if (apiKey.id === activeKey.id) {
            return { ...apiKey, lastUsedAt: apiKey.lastUsedAt ?? null };
          }
          return apiKey;
        }) || [];
      setApiKeysLocal(updatedApiKeys);
      toast.success(t("workspace.api_keys.api_key_rotated"));
      setIsLoading(false);
    } else {
      toast.error(t("workspace.api_keys.unable_to_rotate_api_key"));
      setIsLoading(false);
    }
  };

  const handleAddAPIKey = async (data: {
    label: string;
    workspacePermissions: Array<{
      permission: ApiKeyPermission;
      workspaceId: string;
    }>;
    organizationAccess: TOrganizationAccess;
  }): Promise<void> => {
    setIsLoading(true);
    const createApiKeyResponse = await createApiKeyAction({
      organizationId: organizationId,
      apiKeyData: {
        label: data.label,
        workspacePermissions: data.workspacePermissions,
        organizationAccess: data.organizationAccess,
      },
    });

    if (createApiKeyResponse?.data) {
      const updatedApiKeys = [...apiKeysLocal, createApiKeyResponse.data];
      setApiKeysLocal(updatedApiKeys);
      setIsLoading(false);
      toast.success(t("workspace.api_keys.api_key_created"));
    } else {
      setIsLoading(false);
      const errorMessage = getFormattedErrorMessage(createApiKeyResponse);
      toast.error(errorMessage);
    }

    setIsAddAPIKeyModalOpen(false);
  };

  const handleUpdateAPIKey = async (data: TApiKeyUpdateInput) => {
    if (!activeKey) return;

    const updateApiKeyResponse = await updateApiKeyAction({
      apiKeyId: activeKey.id,
      apiKeyData: data,
    });

    if (updateApiKeyResponse?.data) {
      const updatedApiKeys =
        apiKeysLocal?.map((apiKey) => {
          if (apiKey.id === activeKey.id) {
            return {
              ...apiKey,
              label: data.label,
            };
          }
          return apiKey;
        }) || [];

      setApiKeysLocal(updatedApiKeys);
      toast.success(t("workspace.api_keys.api_key_updated"));
      setIsLoading(false);
    } else {
      const errorMessage = getFormattedErrorMessage(updateApiKeyResponse);
      toast.error(errorMessage);
      setIsLoading(false);
    }

    setViewPermissionsOpen(false);
  };

  return (
    <>
      {/* Moved above the table, matching every other settings table in this series — and required, since
          a flush card body means the table has to be the last thing in it. The control carries the card's
          gutter itself. */}
      <div className="mb-4 flex justify-end px-4 pt-4">
        <Button
          size="sm"
          onClick={() => {
            setIsAddAPIKeyModalOpen(true);
          }}>
          {t("workspace.settings.api_keys.add_api_key")}
        </Button>
      </div>

      <SettingsTable
        columns={getApiKeyColumns({ t, locale, onDelete: handleOpenDeleteKeyModal })}
        rows={apiKeysLocal}
        getRowId={(apiKey) => apiKey.id}
        emptyMessage={t("workspace.api_keys.no_api_keys_yet")}
        getRowProps={() => ({ "data-testid": "api-key-row" })}
        aria-label={t("common.api_keys")}
        onRowClick={(apiKey) => {
          setActiveKey(apiKey);
          setViewPermissionsOpen(true);
        }}
        getRowLabel={(apiKey) => t("workspace.api_keys.view_permissions_for", { label: apiKey.label })}
      />

      <AddApiKeyModal
        open={isAddAPIKeyModalOpen}
        setOpen={setIsAddAPIKeyModalOpen}
        onSubmit={handleAddAPIKey}
        workspaces={workspaces}
        isCreatingAPIKey={isLoading}
        isFormbricksCloud={isFormbricksCloud}
        canGrantOrganizationWriteAccess={canGrantOrganizationWriteAccess}
      />
      {activeKey && (
        <ViewPermissionModal
          open={viewPermissionsOpen}
          setOpen={setViewPermissionsOpen}
          onSubmit={handleUpdateAPIKey}
          apiKey={activeKey}
          workspaces={workspaces}
          isUpdating={isLoading}
        />
      )}
      <DeleteDialog
        open={isDeleteKeyModalOpen}
        setOpen={setIsDeleteKeyModalOpen}
        deleteWhat={t("workspace.api_keys.api_key")}
        onDelete={handleDeleteKey}
        isDeleting={isLoading}
        text={t("workspace.api_keys.delete_api_key_confirmation")}
      />
      <Dialog open={isRotateKeyModalOpen} onOpenChange={setIsRotateKeyModalOpen} closeOnOverlayClick={rotatedKey === null}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>{t("workspace.api_keys.rotate_api_key")}</DialogTitle>
          </DialogHeader>
          <DialogBody>
            <p className="mb-4 text-sm text-slate-600">
              {t("workspace.api_keys.rotate_api_key_description")}
            </p>
            {rotatedKey && (
              <div>
                <p className="mb-2 font-medium">{t("workspace.api_keys.new_api_key")}</p>
                <div className="flex items-center gap-2 rounded-lg border border-slate-200 bg-slate-50 p-3">
                  <code className="flex-1 break-all text-sm">{rotatedKey}</code>
                  <FilesIcon
                    className="size-4 cursor-pointer text-slate-500 hover:text-slate-700"
                    onClick={async () => {
                      try {
                        await navigator.clipboard.writeText(rotatedKey);
                        toast.success(t("workspace.api_keys.api_key_copied_to_clipboard"));
                      } catch {
                        toast.error(t("workspace.api_keys.unable_to_copy_api_key"));
                      }
                    }}
                    data-testid="rotate-copy-button"
                  />
                </div>
                <p className="mt-2 text-xs text-slate-500">
                  {t("workspace.api_keys.api_key_security_warning")}
                </p>
              </div>
            )}
          </DialogBody>
          <DialogFooter>
            {rotatedKey && (
              <Button
                variant="outline"
                onClick={() => {
                  setRotatedKey(null);
                  setIsRotateKeyModalOpen(false);
                }}>
                {t("common.close")}
              </Button>
            )}
            <Button
              variant="secondary"
              onClick={() => {
                setIsRotateKeyModalOpen(false);
                setRotatedKey(null);
              }}>
              {t("common.cancel")}
            </Button>
            <Button
              onClick={handleRotateKey}
              disabled={isLoading || rotatedKey !== null}
              className="bg-amber-600 text-white hover:bg-amber-700">
              {isLoading ? t("common.rotating") : t("workspace.api_keys.confirm_rotate")}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
};

"use server";

import { z } from "zod";
import { ZId } from "@formbricks/types/common";
import { assertCan } from "@/lib/authorization";
import { capturePostHogEvent } from "@/lib/posthog";
import { authenticatedActionClient } from "@/lib/utils/action-client";
import { getOrganizationIdFromApiKeyId } from "@/lib/utils/helper";
import { withAuditLogging } from "@/modules/ee/audit-logs/lib/handler";
import {
  createApiKey,
  deleteApiKey,
  rotateApiKey,
  updateApiKey,
} from "@/modules/organization/settings/api-keys/lib/api-key";
import { assertCanGrantOrganizationAccess } from "@/modules/organization/settings/api-keys/lib/organization-access";
import { ZApiKeyCreateInput, ZApiKeyUpdateInput } from "./types/api-keys";

const ZDeleteApiKeyAction = z.object({
  id: ZId,
});

export const deleteApiKeyAction = authenticatedActionClient.inputSchema(ZDeleteApiKeyAction).action(
  withAuditLogging("deleted", "apiKey", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromApiKeyId(parsedInput.id);
    await assertCan({ type: "user", id: ctx.user.id }, "apiKey.manage", {
      type: "apiKey",
      id: parsedInput.id,
    });

    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.apiKeyId = parsedInput.id;

    const result = await deleteApiKey(parsedInput.id);
    ctx.auditLoggingCtx.oldObject = result;
    return result;
  })
);

const ZCreateApiKeyAction = z.object({
  organizationId: ZId,
  apiKeyData: ZApiKeyCreateInput,
});

const ZRotateApiKeyAction = z.object({
  apiKeyId: ZId,
});

export const rotateApiKeyAction = authenticatedActionClient.inputSchema(ZRotateApiKeyAction).action(
  withAuditLogging("rotated", "apiKey", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromApiKeyId(parsedInput.apiKeyId);
    await assertCan({ type: "user", id: ctx.user.id }, "apiKey.manage", {
      type: "apiKey",
      id: parsedInput.apiKeyId,
    });

    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.apiKeyId = parsedInput.apiKeyId;

    const result = await rotateApiKey(parsedInput.apiKeyId, ctx.user.id);
    ctx.auditLoggingCtx.newObject = { lookupHash: result.lookupHash };
    return result;
  })
);

export const createApiKeyAction = authenticatedActionClient.inputSchema(ZCreateApiKeyAction).action(
  withAuditLogging("created", "apiKey", async ({ ctx, parsedInput }) => {
    await assertCan({ type: "user", id: ctx.user.id }, "organization.manage_api_keys", {
      type: "organization",
      id: parsedInput.organizationId,
    });

    // Managing API keys and managing organization users are two different capabilities, and a key
    // carrying `accessControl.write` grants the second. Gate it on the org's user-management floor so
    // an install that restricts user management to owners cannot have that restriction minted away.
    await assertCanGrantOrganizationAccess(
      ctx.user.id,
      parsedInput.organizationId,
      parsedInput.apiKeyData.organizationAccess
    );

    ctx.auditLoggingCtx.organizationId = parsedInput.organizationId;

    const result = await createApiKey(parsedInput.organizationId, ctx.user.id, parsedInput.apiKeyData);
    ctx.auditLoggingCtx.newObject = parsedInput.apiKeyData;
    ctx.auditLoggingCtx.apiKeyId = result.id;
    capturePostHogEvent(
      ctx.user.id,
      "api_key_created",
      { api_key_id: result.id },
      { organizationId: parsedInput.organizationId }
    );
    return result;
  })
);

const ZUpdateApiKeyAction = z.object({
  apiKeyId: ZId,
  apiKeyData: ZApiKeyUpdateInput,
});

export const updateApiKeyAction = authenticatedActionClient.inputSchema(ZUpdateApiKeyAction).action(
  withAuditLogging("updated", "apiKey", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromApiKeyId(parsedInput.apiKeyId);
    await assertCan({ type: "user", id: ctx.user.id }, "apiKey.manage", {
      type: "apiKey",
      id: parsedInput.apiKeyId,
    });

    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.apiKeyId = parsedInput.apiKeyId;
    ctx.auditLoggingCtx.newObject = parsedInput.apiKeyData;
    return await updateApiKey(parsedInput.apiKeyId, parsedInput.apiKeyData);
  })
);

import "server-only";
import { randomBytes } from "node:crypto";
import { cache as reactCache } from "react";
import { prisma } from "@formbricks/database";
import { ApiKey, ApiKeyPermission, Prisma } from "@formbricks/database/prisma";
import { logger } from "@formbricks/logger";
import { TOrganizationAccess } from "@formbricks/types/api-key";
import { ZId } from "@formbricks/types/common";
import { DatabaseError, OperationNotAllowedError } from "@formbricks/types/errors";
import { reconcileApiKeyRelationships } from "@/lib/authzed/api-key";
import { runPostCommitProjection } from "@/lib/authzed/projection-boundary";
import { CONTROL_HASH } from "@/lib/constants";
import { hashSecret, hashSha256, parseApiKeyV2, verifySecret } from "@/lib/crypto";
import { validateInputs } from "@/lib/utils/validate";
import { getWorkspacesByOrganizationId } from "@/modules/organization/settings/api-keys/lib/workspaces";
import {
  TApiKeyCreateInput,
  TApiKeyUpdateInput,
  TApiKeyWithEnvironmentAndWorkspace,
  TApiKeyWithEnvironmentPermission,
  ZApiKeyCreateInput,
} from "@/modules/organization/settings/api-keys/types/api-keys";

export const getApiKeysWithEnvironmentPermissions = reactCache(
  async (organizationId: string): Promise<TApiKeyWithEnvironmentPermission[]> => {
    validateInputs([organizationId, ZId]);

    try {
      const apiKeys = await prisma.apiKey.findMany({
        where: {
          organizationId,
        },
        select: {
          id: true,
          label: true,
          createdAt: true,
          lastUsedAt: true,
          organizationAccess: true,
          apiKeyWorkspaces: {
            select: {
              permission: true,
              workspaceId: true,
            },
          },
        },
      });
      return apiKeys;
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) {
        throw new DatabaseError(error.message);
      }
      throw error;
    }
  }
);

// Get API key with its permissions from a raw API key
export const getApiKeyWithPermissions = reactCache(
  async (apiKey: string): Promise<TApiKeyWithEnvironmentAndWorkspace | null> => {
    try {
      const includeQuery = {
        apiKeyWorkspaces: {
          include: {
            workspace: {
              select: {
                id: true,
                name: true,
                // ENG-1749: needed so the auth layer can drop any workspace permission whose
                // workspace is outside the key's organization (defense-in-depth for the read path,
                // which authorizes off the permission list rather than resolveBodyIdsV2).
                organizationId: true,
              },
            },
          },
        },
      };

      // Try v2 format first (fbk_{secret})
      const v2Parsed = parseApiKeyV2(apiKey);

      let apiKeyData;

      if (v2Parsed) {
        // New v2 format (fbk_{secret}): Hybrid approach
        // Step 1: Fast SHA-256 lookup by indexed lookupHash
        const lookupHash = hashSha256(v2Parsed.secret);
        apiKeyData = await prisma.apiKey.findUnique({
          where: { lookupHash },
          include: includeQuery,
        });

        // Step 2: Security verification with bcrypt
        // Always perform bcrypt verification to prevent timing attacks
        // Use a control hash when API key doesn't exist to maintain constant timing
        const hashToVerify = apiKeyData?.hashedKey || CONTROL_HASH;
        const isValid = await verifySecret(v2Parsed.secret, hashToVerify);

        if (!apiKeyData || !isValid) {
          if (apiKeyData && !isValid) {
            logger.warn({ apiKeyId: apiKeyData.id }, "API key bcrypt verification failed");
          }
          return null;
        }
      } else {
        // Legacy format: compute SHA-256 and lookup by hashedKey
        const hashedKey = hashSha256(apiKey);
        apiKeyData = await prisma.apiKey.findFirst({
          where: { hashedKey: hashedKey },
          include: includeQuery,
        });

        if (!apiKeyData) return null;
      }

      if (!apiKeyData.lastUsedAt || apiKeyData.lastUsedAt <= new Date(Date.now() - 1000 * 30)) {
        // Fire-and-forget: update lastUsedAt in the background without blocking the response
        // Update on first use (null) or if last used more than 30 seconds ago
        prisma.apiKey
          .update({
            where: { id: apiKeyData.id },
            data: { lastUsedAt: new Date() },
          })
          .catch((error) => {
            logger.error({ error }, "Failed to update API key usage");
          });
      }

      return apiKeyData as TApiKeyWithEnvironmentAndWorkspace;
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) {
        throw new DatabaseError(error.message);
      }

      throw error;
    }
  }
);

export const deleteApiKey = async (id: string): Promise<ApiKey | null> => {
  validateInputs([id, ZId]);

  try {
    const deletedApiKeyData = await prisma.apiKey.delete({
      where: {
        id: id,
      },
    });

    await runPostCommitProjection("api_key_delete_relationship_reconciliation", () =>
      reconcileApiKeyRelationships({ apiKeyIds: [id] })
    );

    return deletedApiKeyData;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }
};


export const rotateApiKey = async (
  apiKeyId: string,
  userId: string
): Promise<TApiKeyWithEnvironmentPermission & { actualKey: string }> => {
  validateInputs([apiKeyId, ZId]);
  try {
    // Fetch the existing key to copy its settings
    const existing = await prisma.apiKey.findUnique({
      where: { id: apiKeyId },
      include: { apiKeyWorkspaces: true },
    });

    if (!existing) {
      throw new OperationNotAllowedError("API key not found");
    }

    // Generate a new secret
    const secret = randomBytes(32).toString("base64url");
    const lookupHash = hashSha256(secret);
    const hashedKey = await hashSecret(secret, 12);

    // Replace the key: update hashedKey and lookupHash, keep everything else
    const updated = await prisma.apiKey.update({
      where: { id: apiKeyId },
      data: { hashedKey, lookupHash, updatedAt: new Date() },
      include: { apiKeyWorkspaces: true },
    });

    await runPostCommitProjection("api_key_rotate_relationship_reconciliation", () =>
      reconcileApiKeyRelationships({ apiKeyIds: [apiKeyId] })
    );

    return { ...updated, actualKey: `fbk_${secret}` };
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }
    throw error;
  }
};

export const createApiKey = async (
  organizationId: string,
  userId: string,
  apiKeyData: TApiKeyCreateInput & {
    workspacePermissions?: Array<{
      workspaceId: string;
      permission: ApiKeyPermission;
    }>;
    organizationAccess: TOrganizationAccess;
  }
): Promise<TApiKeyWithEnvironmentPermission & { actualKey: string }> => {
  validateInputs([organizationId, ZId], [apiKeyData, ZApiKeyCreateInput]);
  try {
    // ENG-1749: an API key is created at the organization level but carries per-workspace
    // permissions. Reject any workspace that does not belong to the authorized organization,
    // otherwise a caller could mint a key scoped to another tenant's workspace (cross-tenant
    // BOLA). Validate before generating/hashing the secret so illegitimate input does no work.
    const { workspacePermissions, organizationAccess, ...apiKeyDataWithoutPermissions } = apiKeyData;
    if (workspacePermissions && workspacePermissions.length > 0) {
      const orgWorkspaceIds = new Set(
        (await getWorkspacesByOrganizationId(organizationId)).map((workspace) => workspace.id)
      );
      for (const { workspaceId } of workspacePermissions) {
        if (!orgWorkspaceIds.has(workspaceId)) {
          throw new OperationNotAllowedError(
            `Workspace ${workspaceId} does not belong to organization ${organizationId}`
          );
        }
      }
    }

    // Generate a secure random secret (32 bytes base64url)
    const secret = randomBytes(32).toString("base64url");

    // Hybrid approach for security + performance:
    // 1. SHA-256 lookup hash
    const lookupHash = hashSha256(secret);

    // 2. bcrypt hash
    const hashedKey = await hashSecret(secret, 12);

    // Create the API key
    const result = await prisma.apiKey.create({
      data: {
        ...apiKeyDataWithoutPermissions,
        hashedKey,
        lookupHash,
        createdBy: userId,
        organization: { connect: { id: organizationId } },
        organizationAccess,
        ...(workspacePermissions && workspacePermissions.length > 0
          ? {
              apiKeyWorkspaces: {
                create: workspacePermissions.map((wsPerm) => ({
                  permission: wsPerm.permission,
                  workspaceId: wsPerm.workspaceId,
                })),
              },
            }
          : {}),
      },
      include: {
        apiKeyWorkspaces: true,
      },
    });

    await runPostCommitProjection("api_key_create_relationship_reconciliation", () =>
      reconcileApiKeyRelationships({ apiKeyIds: [result.id] })
    );

    // Return the new v2 format: fbk_{secret}
    return { ...result, actualKey: `fbk_${secret}` };
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }
    throw error;
  }
};

export const updateApiKey = async (apiKeyId: string, data: TApiKeyUpdateInput): Promise<ApiKey | null> => {
  try {
    const updatedApiKey = await prisma.apiKey.update({
      where: {
        id: apiKeyId,
      },
